OBJECT_SIZE_CHOICES = (3, 4, 5)
GEN_RETRIES = 400

# Rooted half-plane fallback shapes for the top-contact case.
FALLBACK_SHAPES = (
    {(0, 0), (1, 0), (1, 1)},
    {(0, 0), (1, 0), (2, 0), (2, 1)},
    {(0, 0), (1, 0), (1, 1), (2, 1)},
    {(0, 0), (1, 0), (2, 0), (1, 1)},
